pub(crate) fn map(c: char, upper: bool) -> char {
    let point = c as u32;
    let index = RANGES.partition_point(|&(_, high, _, _)| high < point);
    let Some(&(low, _, up, down)) = RANGES.get(index).filter(|&&(low, _, _, _)| point >= low)
    else {
        return c;
    };
    let delta = if upper { up } else { down };
    let mapped = if delta == 0x110000 {
        low + ((point - low) & !1) + u32::from(!upper)
    } else {
        (point as i32 + delta) as u32
    };
    char::from_u32(mapped).unwrap()
}

